from six.moves import urllib
import re
import subprocess
from robot.api import logger
import os


class TsharkSetup:
    def __init__(self):
        self.default_url = "https://artifactory-hz1.int.net.nokia.com/artifactory/wslte5g_plugins-local/Nokia_F1_AP/"  # noqa: E501
        self.default_tshark_plugin_dir = self._get_default_tshark_plugin_dir()
        self.ute_token_dir = '/etc/token/ca_ute_artifactory_readonly'
        self.ute_token = None

    def _get_default_tshark_plugin_dir(self):
        try:
            tshark_version = self._get_tshark_version()[:3]
            output_filepath = "/usr/lib/x86_64-linux-gnu/wireshark/plugins/{}/epan/".format(tshark_version)
        except Exception:
            output_filepath = "/usr/lib/x86_64-linux-gnu/wireshark/plugins/4.4/epan/"
        return output_filepath

    def _get_readonly_ute_token(self):
        """
        Return required read-only token to access artifactory
        :return:
        """
        if self.ute_token is not None:
            return self.ute_token
        if os.path.exists(self.ute_token_dir):
            with open(self.ute_token_dir, 'r') as token_file:
                token = token_file.read().strip()
            if token:
                self.ute_token = token
                return token
        return None

    def setup_tshark_with_nokia_f1ap_plugin(self,
                                            output_filepath=None,
                                            url=None):
        """
        :param output_filepath:
        :param url:
        """
        if url is None:
            url = self.default_url

        tshark_ver, linux_build = self._get_tshark_version().split("+")
        download_url = self._navigate_to_plugins_web_dir_and_get_file_url(
            tshark_ver, linux_build, url
        )
        self._save_file_to_dir(download_url, output_filepath)

    def _navigate_to_plugins_web_dir_and_get_file_url(
        self, tshark_ver, linux_build, url
    ):
        for i in range(-1, -6, -1):
            latest_build = self._filter_urls_from_html(url)[i]
            url_to_latest_build = url + latest_build

            list_of_files = self._filter_urls_from_html(url_to_latest_build)
            tshark_ver = tshark_ver[:3]
            for file in list_of_files:
                if (
                    linux_build in file and tshark_ver in file and file[-3:] == ".so"
                ):  # E501: noqa
                    file_to_download = file
                    return url_to_latest_build + file_to_download
        else:
            raise Exception("Couldn't find file matching with tshark ver.")

    def _get_tshark_version(self):
        output = subprocess.check_output(["dpkg", "-l", "ute-wireshark"])
        string_output = output.decode('utf-8')
        for line in string_output.split():
            if "bookworm" in line:
                return str(line)
        else:
            raise Exception("Unable to find tshark version.")

    def _filter_urls_from_html(self, url):
        token = self._get_readonly_ute_token()
        headers = {'Authorization': 'Bearer {}'.format(token)}
        request = urllib.request.Request(url, headers=headers)

        try:
            url_list = re.findall(
                r"""<\s*a\s*href=["']([^=]+)["']""",
                urllib.request.urlopen(request).read().decode("utf-8"),
            )
        except urllib.error.HTTPError:
            logger.warn("Error 404 - provided URL not found.")
            raise
        except ValueError:
            logger.warn("Value error - provided URL is not correct.")
            raise

        return url_list

    def _save_file_to_dir(self, url, output_filepath=None):
        token = self._get_readonly_ute_token()
        headers = {'Authorization': 'Bearer {}'.format(token)}
        request = urllib.request.Request(url, headers=headers)
        if output_filepath is None:
            self._grant_user_access_to_default_tshark_plugins_dir()
            output_filepath = self.default_tshark_plugin_dir + "nokiaf1ap.so"  # noqa: E501
        try:
            with urllib.request.urlopen(request) as response:
                with open(output_filepath, 'wb') as f:
                    f.write(response.read())
        except FileNotFoundError:  # noqa: F821
            logger.warn("Provided output_filepath doesn't exist.")
            raise

    def _grant_user_access_to_default_tshark_plugins_dir(self):
        try:
            subprocess.run(["sudo", "chown", "ute", self.default_tshark_plugin_dir], check=True)
        except Exception:
            logger.warn("Error occurred during an attempt to chown default plugin directory to user ute.")
            raise
